package main
import("testing";"encoding/binary")
func TestBatteryHysteresis(t *testing.T){cases:=[]struct{c BatteryConfig;p int;want bool}{{BatteryConfig{Enabled:true,Stop:90,Resume:50},90,true},{BatteryConfig{Enabled:true,Stop:90,Resume:50},75,false},{BatteryConfig{Enabled:true,Stop:90,Resume:50,Paused:true},75,true},{BatteryConfig{Enabled:true,Stop:90,Resume:50,Paused:true},50,false},{BatteryConfig{Stop:90,Resume:50,ManualPaused:true},25,true},{BatteryConfig{Stop:90,Resume:50,Paused:true},90,false}};for _,x:=range cases{if got:=desiredBatteryPause(x.c,x.p);got!=x.want{t.Fatalf("%+v at %d: %v",x.c,x.p,got)}}}
func TestBatteryThresholdValidation(t *testing.T){for _,c:=range []BatteryConfig{{Stop:80,Resume:50},{Stop:75,Resume:75},{Stop:50,Resume:90},{Stop:25,Resume:15},{Stop:90,Resume:0}}{if validateBatteryConfig(c)==nil{t.Fatalf("invalid config accepted: %+v",c)}};if e:=validateBatteryConfig(BatteryConfig{Stop:90,Resume:75});e!=nil{t.Fatal(e)}}
func TestBatteryDriverSnapshot(t *testing.T){b:=make([]byte,32);b[13]=0x82;binary.LittleEndian.PutUint16(b[24:26],957);s,e:=decodeBattery(b,6);if e!=nil||!s.Charging||s.Percent!=100||s.PowerMode!=2{t.Fatal(s,e)};binary.LittleEndian.PutUint16(b[24:26],11);s,e=decodeBattery(b,4);if e!=nil||s.Charging||s.Percent!=75{t.Fatal(s,e)}}
func TestBatteryRejectsMissingData(t *testing.T){if _,e:=decodeBattery(make([]byte,20),4);e==nil{t.Fatal("short snapshot accepted")};if _,e:=decodeBattery(make([]byte,32),0);e==nil{t.Fatal("unknown level accepted")}}
